// "returns" its results by filling the caller's array
void squares(int out[static 5]) {
    for (int i = 0; i < 5; i++) {
        out[i] = i * i;
    }
}

int main(void) {
    int result[5];
    squares(result);
    for (int i = 0; i < 5; i++) {
        printf("%d ", result[i]);
    }
