#include <stdio.h>

void countdown(int n) {
    if (n == 0) {              // base case: stop
        printf("liftoff\n");
        return;
    }
    printf("%d\n", n);
    countdown(n - 1);          // recursive call on a smaller problem
}

int main(void) {
    countdown(3);
    return 0;
}

#include <stdio.h>

// 1 + 2 + ... + n
int sumto(int n) {
    if (n == 0) {
        return 0;                  // base case
    }
    return n + sumto(n - 1);       // smaller problem
}

int main(void) {
    printf("%d\n", sumto(4));
    printf("%d\n", sumto(100));
    return 0;
}

