#include <stdio.h>

// print the 4 digits on one line
void printdigits(int d[static 4]) {
    for (int i = 0; i < 4; i++) {
        printf("%d", d[i]);
    }
    printf("\n");
}

// "0457" -> [0, 4, 5, 7]
void todigits(const char str[static 4], int d[static 4]) {
    for (int i = 0; i < 4; i++) {
        d[i] = str[i] - '0';
    }
}

// z = x + y using long addition, right to left; returns the final carry
int add4(int x[static 4], int y[static 4], int z[static 4]) {
    int carry = 0;
    for (int i = 3; i >= 0; i--) {
        int s = x[i] + y[i] + carry;
        z[i] = s % 10;
        carry = s / 10;
    }
    return carry;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "usage: %s dddd dddd\n", argv[0]);
        return 1;
    }
    int x[4];
    int y[4];
    int z[4];
    todigits(argv[1], x);
    todigits(argv[2], y);
    printdigits(x);
    printdigits(y);
    int carry = add4(x, y, z);
    printdigits(z);
    if (carry != 0) {
        printf("overflow: carry %d was lost\n", carry);
    }
    return 0;
}

