#include <stdio.h>

// adds 1 to the 4-digit decimal number in d; returns the carry left over
int addone(int d[static 4]) {
    int carry = 1;                 // the 1 we are adding
    for (int i = 3; i >= 0; i--) {
        int s = d[i] + carry;
        d[i] = s % 10;
        carry = s / 10;
    }
    return carry;
}

int main(void) {
    int a[4] = {0, 1, 9, 9};
    int c = addone(a);
    printf("%d%d%d%d carry %d\n", a[0], a[1], a[2], a[3], c);
    int b[4] = {9, 9, 9, 9};
    c = addone(b);
    printf("%d%d%d%d carry %d\n", b[0], b[1], b[2], b[3], c);
    return 0;
}
